Here is one way using plain recursion. It walks the tree depth first and glues each folder name onto the prefix before it goes deeper. Files are stored in the dict as keys whose value is `None`.

```python
def flatten_tree(tree):
    """Return a flat list of path strings from a nested folder dict.

    A folder is a key whose value is another dict.
    A file is a key whose value is None.
    """
    def walk(node, prefix, out):
        for name, value in node.items():
            path = f"{prefix}/{name}" if prefix else name
            if value is None:               # file
                out.append(path)
            else:                           # subfolder
                walk(value, path, out)
        return out

    return walk(tree, "", [])


# Example ----------------------------------------------------------------

folder_tree = {
    "repo": {
        "setup.py": None,
        "README.md": None,
        "src": {
            "api": {
                "index.py": None,
                "routes.py": None,
            },
            "core": {
                "__init__.py": None,
                "loader.py": None,
            },
        },
        "tests": {
            "test_index.py": None,
            "test_loader.py": None,
        },
    }
}

flat = flatten_tree(folder_tree)
for p in flat:
    print(p)
```

Output:

```
