def average_scores(students: dict[str, list[float]]) -> dict[str, float]:
    """
    Compute the average score for each student.

    Parameters:
        students: A mapping from a student name to the list of that
                  student's numeric test scores. Scores are expected to
                  be real numbers (int or float).

    Returns:
        A new dictionary mapping each student to the arithmetic mean of
        their scores, rounded to one decimal place. Students with an
        empty score list are omitted from the result.

    Example:
        >>> average_scores({"Ada": [90, 80], "Bo": [100, 70, 60]})
        {'Ada': 85.0, 'Bo': 76.7}
    """
    return {
        name: round(sum(scores) / len(scores), 1)
        for name, scores in students.items()
        if scores  # skip students whose list is empty
    }

