from dataclasses import dataclass
from typing import Dict, Iterator, List, Set


FAIL_THRESHOLD = 50
MISSING_SCORE = None  # sentinel value, but you can use a constant string instead


@dataclass
class StudentRecord:
    """One row of a grade sheet, indexed by subject names."""
    student_id: str
    grades: Dict[str, int]  # subject → score

    def failing_subjects(self) -> Iterator[str]:
