def group_by_first_letter(words: list[str]) -> dict[str, list[str]]:
    """Group words by their first letter.

    Returns an empty dict for an empty input. Empty strings are skipped,
    since they have no first character. The first character is used as
    the key exactly as it appears; case is preserved.
    """
    if not words:
        return {}

    groups: dict[str, list[str]] = {}
    for word in words:
        if not word:
            continue
        key = word[0]
        if key not in groups:
            groups[key] = []
        groups[key].append(word)

    return groups
