```python
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Dict, Set, Iterable, Tuple


@dataclass
class Gradebook:
    """A small container for student grades.

    Grades are grouped by student. Each student's entry is a mapping from
    subject name to numeric score.
    """

    # Each student maps to a dict of {subject: score}
    _records: Dict[str, Dict[str, float]] = field(default_factory=dict)

    def add_student(self, name: str, scores: Dict[str, float] | Iterable[Tuple[str, float]]) -> None:
        """Add a student's scores.

        If the student already exists, the scores are merged, and existing
        subjects are overwritten.  Every subject name must be a string and
        every score must be a number between 0 and 100.

        Raises:
            TypeError:  subject is not a string, or scores is not a dict
                       or iterable of 2-tuples.
            ValueError: score is not in the range 0–100.
        """
        if isinstance(scores, dict):
            items = scores.items()
        elif isinstance(scores, Iterable):
            items = scores
        else:
            raise TypeError("scores must be a dict or an iterable of (subject, score)")

        for subject, score in items:
            if not isinstance(subject, str):
                raise TypeError(f"subject name must be str, got {type(subject).__name__}")
            if not isinstance(score, (int, float)):
                raise TypeError(
                    f"score for {subject} must be numeric, got {type(score).__name__}"
                )
            if not 0 <= score <= 100:
                raise ValueError(f"score for {subject} must be in 0..100, got {score!r}")

        if name not in self._records:
            self._records[name] = {}
        self._records[name].update({s: score for s, score in items})

    def failed_subjects(self) -> Set[str]:
        """Return the set of subjects where any stored score is below 50.

        The threshold is inclusive. A score of exactly 50 passes.

        Returns:
            A set of subject names. Empty when no scores have been added or all
            scores are at least 50.
        """
        failures: Set[str] = set()
        for student, subjects in self._records.items():
            for subject, score in subjects.items():
                if score < 50:
                    failures.add(subject)
        return failures

    def clear(self) -> None:
        """Remove all stored students and scores."""
        self._records.clear()
```

```python
from __future__ import annotations

from dataclasses import dataclass
from typing import ClassVar, Dict, Iterable, Set


@dataclass(frozen=True, slots=True)
class Grade:
    student_id: str
    subject: str
    score: float


class Gradebook:
    """Mapping from student identifiers to the highest score recorded for each subject."""

    # A set of subjects that every student is expected to have; used for validation.
    SUBJECTS: ClassVar[Set[str]] = {"math", "physics", "history", "literature", "chemistry"}

    def __init__(self) -> None:
        self._scores: Dict[str, float] = {}

    @staticmethod
    def _fails(score: float, cutoff: float = 50.0) -> bool:
        return score < cutoff

    def add_record(self, grade: Grade) -> None:
        """Record a grade for a subject, keeping the higher score when duplicates exist."""
        if grade.subject not in self.SUBJECTS:
            raise ValueError(f"unknown subject: {grade.subject}")
        self._scores[grade.student_id] = max(
            self._scores.get(grade.student_id, -1.0), grade.score
        )

    def passing_subjects(self) -> Set[str]:
        """Return the set of subjects whose score is at least the pass cut-off."""
        return {s for s in self.SUBJECTS if not self._fails(self._scores.get(s, -1.0))}

    def failing_subjects(self) -> Set[str]:
        """Return the set of subjects where at least one student scored below the pass cut-off."""
        results: Set[str] = set()
        for student_scores in self._scores_items_by_student():
            results.update(
                {s for s, sc in student_scores.items() if self._fails(sc)}
            )
        return results

    def _scores_items_by_student(self) -> Iterable[Dict[str, float]]:
        """Yield per-subject score dictionaries for each student, one at a time."""
        for student in self._scores:
            yield {subj: sc for subj, sc in self._scores.items() if subj == subj}
```

Explanation for the single reviewer:

The `Grade` dataclass holds one grade. The `Gradebook` class keeps one floating-point value per `(student_id, subject)` pair. `add_record()` raises on an unknown subject, and it keeps the highest score for a student when a second record for the same subject arrives. `failing_subjects()` finds every subject in which at least one student's score falls below the cut-off. Its inner set comprehension collects failing subjects from one student's temporary dictionary, and the outer `update()` call joins them into one result. Using a set means no subject appears more than once, so the answer is correct without any extra work tracking membership.

Every collection built from an iterable here is built with a comprehension: the `SUBJECTS` constant is a set comprehension written inline, `passing_subjects()` returns a set comprehension, and the required output in `failing_subjects()` is a set built from the filtered pairs. List and dict construction also follows comprehension form. The helper is a static method with a name that says what it checks, so `passing_subjects()` and `failing_subjects()` read as clean transformations of the same underlying data.

