from __future__ import annotations

from typing import List, Set, Dict

FAILERH_THRESH = 50.0  # the cut-off for a failing subject score


class GradeBook:
    """Stores student dictionaries and reports subjects with any failing score."""

    def __init__(self) -> None:
        self._students: List[Dict] = []

    def add_student(self, student_id: str, name: str, subjects: Dict[str, float]) -> None:
        """Add one student's records.

        Overrides any earlier entry with the same student_id, so totals are taken from
        the most recent call for that ID.
        """
        self.remove_student(student_id)
        self._students.append({"id": student_id, "name": name, "score": subjects})

    def remove_student(self, student_id: str) -> None:
        """Drop every record for the given student ID."""
        remaining: List[Dict] = []
        for record in self._students:
            if record["id"] != student_id:
                remaining.append(record)
        self._students = remaining

    def failing_subjects(self) -> Set[str]:
        """Return subjects where any stored student scored below the threshold."""
        flags: Set[str] = set()
        for record in self._students:
            for subject, score in record["score"].items():
                if score < FAILERH_THRESH:
                    flags.add(subject)
        return flags


if __name__ == "__main__":
    gb = GradeBook()
    gb.add_student("007", "Jodie Lindqvist", {"logic": 61, "calculus": 48, "statistics": 77})
    gb.add_student("014", "Quentin Osei", {"logic": 72, "calculus": 55, "statistics": 44})
    print(gb.failing_subjects())
    # Output: {'statistics', 'calculus'}
    # statistics because of the 44 in the second record;
    # calculus because of the 48 in the first record.

