from typing import Dict, Set


class Gradebook:
    """Record grades per student and report subjects with any failing score."""

    FAILING_SCORE = 50

    def __init__(self) -> None:
        # student name -> {subject: score}
        self._records: Dict[str, Dict[str, int]] = {}

    def add_grade(self, student: str, subject: str, score: int) -> None:
        """Store a score for one subject. Scores are kept as whole numbers."""
        if student not in self._records:
            self._records[student] = {}
        self._records[student][subject] = score

    def failing_subjects(self) -> Set[str]:
        """Return subjects where any score is below `FAILING_SCORE`.

        If the book is empty or every score is at or above the threshold,
        the result is an empty set.
        """
        return {
            subject
            for student_grades in self._records.values()
            for subject, score in student_grades.items()
            if score < self.FAILING_SCORE
        }


