from typing import Dict, Set, Iterable

PASS_THRESHOLD = 50.0


class Gradebook:
    """A simple table of student grades indexed by name and subject."""

    def __init__(self, grades: Dict[str, Dict[str, float]] = None):
        self.grades: Dict[str, Dict[str, float]] = grades or {}

    def add_student(self, name: str, scores: Dict[str, float] | Iterable[tuple[str, float]]) -> None:
        if isinstance(scores, dict):
            self.grades[name] = {k: float(v) for k, v in scores.items()}
        else:
