    def set_score(self, name: str, subject: str, score: float) -> None:
        self.grades.setdefault(name, {})[subject] = float(score)

    def failed_subjects(self, threshold: float = PASS_THRESHOLD) -> Set[str]:
        failures = set()
        for name, subjects in self.grades.items():
            for subject, score in subjects.items():
                if score < threshold:
                    failures.add(subject)
