```python
from collections import defaultdict
from typing import Dict, Set, Tuple

class Gradebook:
    """Stores grades for multiple students and provides queries over them."""

    def __init__(self) -> None:
        # { student_name: { subject: score, ... }, ... }
        self._records: Dict[str, Dict[str, float]] = defaultdict(dict)

    def add_grade(self, student: str, subject: str, score: float) -> None:
        """Record a grade for a student in a subject. Scores above 100 are capped at 100."""
        if score < 0:
            raise ValueError("score must be non-negative")
        self._records[student][subject] = min(score, 100)

    def grade(self, student: str, subject: str) -> float | None:
        """Return the stored score, or None if no such record exists."""
        return self._records.get(student, {}).get(subject)

    def subjects_with_any_failure(self) -> Set[str]:
        """Return the set of subjects where any student scored below 50."""
        failing = set()
        for student, subjects in self._records.items():
            for subject, score in subjects.items():
                if score < 50:
                    failing.add(subject)
        return failing

    def average_per_subject(self) -> Dict[str, float]:
        """Return the average score for each subject across all students."""
        totals: Dict[str, float] = {}
        counts: Dict[str, int] = {}
        for subjects in self._records.values():
            for subject, score in subjects.items():
                totals[subject] = totals.get(subject, 0.0) + score
                counts[subject] = counts.get(subject, 0) + 1
        return {s: totals[s] / counts[s] for s in totals}

    def clear(self) -> None:
        """Remove all stored records."""
        self._records.clear()


# Simple sanity check (run this in a script or REPL):
if __name__ == "__main__":
    g = Gradebook()
    g.add_grade("Ana", "Mathematics", 92)
    g.add_grade("Ana", "History", 47)
    g.add_grade("Tom", "Mathematics", 58)
    g.add_grade("Tom", "History", 61)
    print(g.subjects_with_any_failure())      # Output: {'History'}
    print(g.average_per_subject())            # Output: {'Mathematics': 75.0, 'History': 54.0}
```

**Explanation of design choices**

- `defaultdict(dict)` removes the need to check whether a student exists before adding a grade.
- Scores are capped at 100 in `add_grade` under an assumption that the input may occasionally exceed that maximum. If your system guarantees valid input, you can remove the `min` call.
- Returning `float | None` from `grade` makes it explicit when a record is missing. Callers can check for `None` or handle it with `or`.
- `subjects_with_any_failure` builds its result in a single pass. A set guarantees each subject appears at most once even if several students fail in it, which matches the specification.
- A separate `clear` method is provided so that unit tests can start from a clean state without recreating the object.
- Type hints use plain `float` for all grade values. If your institution uses a different numeric type, such as `Decimal` for weighted scores, declare that in the imports and in each annotation.

