from typing import Dict

APP_PREFIX = "APP_"

def normalize_app_env(raw_env: Dict[str, str]) -> Dict[str, str]:
    """Return entries whose keys start with APP_, with the prefix removed.

    Keys that do not start with APP_ are skipped. The values are passed
    through unchanged.

    Example:
        {"APP_HOST": "us-west", "DB_URL": "..."}
        -> {"HOST": "us-west"}
    """
    return {
        key[len(APP_PREFIX) :]: value
        for key, value in raw_env.items()
        if key.startswith(APP_PREFIX)
