def drop_app_prefix(env: dict) -> dict:
    """Return a new dict with keys starting with `APP_` stripped of that prefix.

    Keys that do not start with the prefix are dropped. Non-string keys are
    ignored so that the function does not raise a TypeError when a dict
    contains unexpected key types.

    Args:
        env: Mapping of environment variable names to their values.

    Returns:
        A dictionary whose keys no longer contain `APP_` at the start.
    """
    return {
        name[4:]: value
        for name, value in env.items()
        if isinstance(name, str) and name.startswith("APP_")
    }
