from typing import Any, Iterable, Mapping, Set

def has_events_on_weekday(
    schedule: Mapping[str, Iterable[Any] | None],
) -> Set[str]:
    """Return the weekday names that have at least one event.

    The schedule maps a weekday name to an iterable of events or to None.
    Weekdays with missing keys, an empty container, or None are excluded
    from the result. Empty dictionaries are returned when no weekday has
    events.

    Args:
        schedule: A mapping from weekday names to iterables of events.

    Returns:
        A set containing the names of weekdays that have at least one event.
    """
    active_days: Set[str] = set()
    for day, events in schedule.items():
        if events is None:
            continue
        has_one = False
        for _ in events:
            has_one = True
            break
        if has_one:
            active_days.add(day)
    return active_days


