from __future__ import annotations

import unittest
from datetime import date
from typing import Dict, List, Set

# Event records are simple dictionaries: {"daytype": "weekday" or "weekend"}
Schedule = Dict[str, List[dict[str, str]]]


def weekday_names(schedule: Schedule) -> Set[str]:
    """Return weekday names with at least one event in the given schedule.

    The schedule maps ISO date strings (YYYY-MM-DD) to a list of event
    records.  Each record carries a `daytype` field containing either
    "weekday" or "weekend".
    """
    return {
        date.fromisoformat(date_key).strftime("%A")
        for date_key, events in schedule.items()
        if any(ev["daytype"] == "weekday" for ev in events)
    }


class TestWeekdayNames(unittest.TestCase):
