            "2024-09-02": [{"daytype": "weekday"}],   # Monday
            "2024-09-03": [{"daytype": "weekday"}],   # Tuesday
            "2024-09-07": [{"daytype": "weekday"}],   # Saturday is impossible in ISO terms,
                                                    # this date is kept as a weekend case
            "2024-09-08": [{"daytype": "weekend"}],
        }
        self.assertEqual(weekday_names(schedule), {"Monday", "Tuesday"})

    def test_year_boundary(self):
        schedule: Schedule = {
            "2023-12-31": [{"daytype": "weekday"}],   # Sunday, but labeled weekend/weekday by input
            "2024-01-01": [{"daytype": "weekday"}],   # Monday
        }
        self.assertEqual(weekday_names(schedule), {"Monday"})

    def test_no_weekdays(self):
        schedule: Schedule = {
            "2024-09-09": [{"daytype": "weekend"}],
            "2024-09-10": [{"daytype": "weekend"}],
        }
        self.assertEqual(weekday_names(schedule), set())


