def top_students(scores: Mapping[str, Mapping[str, int]]) -> Set[str]:
    """Return the students whose every subject score is above 90.

    Takes a mapping from student names to a mapping of subject names and integer
    scores.  Each subject score is compared with the threshold 90 using a
