def read_csv_columns(csv_text: str) -> dict[str, list[str]]:
    """Parse CSV text into a mapping of column name to column values.

    The input is expected to contain a header row followed by data rows.
    Empty lines are ignored. Every value is stripped of surrounding
    whitespace; header cells are used as they appear.

    Returns:
        dict[str, list[str]]: keys are header names and values are lists of
            cell contents in file order.
    """
    lines = csv_text.splitlines()

    header = None
    rows = []
    for line in lines:
        stripped = line.strip()
        if stripped == "":
            continue
        cells = stripped.split(",")
        if header is None:
            header = cells
        else:
            rows.append(cells)

    # Build the result column by column
    column_map: dict[str, list[str]] = {}
    for head in header:
        column_map[head] = []

    for row in rows:
        col_index = 0
        while col_index < len(header):
            result_cell = row[col_index].strip()
            column_map[header[col_index]].append(result_cell)
            col_index += 1

    return column_map
```

