        "flour": 300.0,
        "sugar": 150.0,
    }


def test_returns_new_dict_even_when_factor_is_one():
    source = {"salt": 5}
    result = scale_recipe(source, 1.0)
    assert result is not source and result == {"salt": 5.0}
    result["salt"] = 10.0
    assert source["salt"] == 5.0


