"""češka_kod_lab.kuharicno_kodiranje

Pripravlja meritve sestavin v receptu, pomnožene z danim faktorjem.
Sestavna listi (recepti) so slovarji, kjer je ključ ime sestavine in
vrednost količina. Negativne količine niso preverjane; naj se to definira
prej, preden se recept skalarja.

Služi za pripravo enotnih testnih primerov in za ročne recepte, ki jih
konstruktor prilagodi in potem pošlje v predvajalnik.
"""

def _is_number(value):
    """Vrne True, če je vrednost int ali float, sicer False."""
    return isinstance(value, (int, float))


def scale_recipe(recipe, factor):
    """Skalar količine v receptu.

    Vsako numerično količino v slovarju `recipe` pomnoži z `factor` in
    vrne nov slovar. Neprevedljive količine (besedila, npr. "po okusu")
    se prenehajo in ostanejo nespremenjene.

    Primer:
        >>> scale_recipe({"moka": 2, "sladkor": 1}, 2)
        {"moka": 4, "sladkor": 2}
    """
    paused = {}
    for name, qty in recipe.items():
        if not _is_number(qty):
            paused[name] = qty
            continue
        paused[name] = qty * factor
    return paused


if __name__ == "__main__":
    assert scale_recipe({"moka": 2, "sladkor": 1}, 2) == {"moka": 4, "sladkor": 2}
    assert scale_recipe({"sol": "po okusu", "oliwa": 0.5}, 3) == {
        "sol": "po okusu",
        "oliwa": 1.5,
    }
    assert scale_recipe({}, 10) == {}
    print("all basic tests passed")
```

