from __future__ import annotations

import datetime as _dt
from typing import Iterable, List


def weekend_orders(timestamps: Iterable[str]) -> List[str]:
    """Return weekend order dates formatted as "day-month-year".

    Timestamps are parsed as UTC. A trailing "Z" is stripped before
    parsing. Saturday (weekday 5) and Sunday (weekday 6) are kept.
    """
    return [
        d.strftime("%d-%m-%Y")
        for d in (
            (
                _dt.datetime.fromisoformat(
                    ts[:-1] if ts.endswith("Z") else ts
                )
            ).astimezone(_dt.timezone.utc)
            for ts in timestamps
        )
        if d.weekday() in {5, 6}
    ]


if __name__ == "__main__":
    sample = [
        "2024-10-12T08:30:00Z",   # Saturday
        "2024-10-13T19:15:00Z",   # Sunday
        "2024-10-14T12:00:00",    # Monday, no Z
    ]
    print(weekend_orders(sample))
```

```python
import datetime


def is_weekend(order: datetime.datetime) -> bool:
    """Return True when the order falls on Saturday or Sunday."""
    weekday = order.date().weekday()  # Monday is 0, Sunday is 6
    return weekday >= 5


def format_date(order: datetime.datetime) -> str:
    """Return the order date as DD-MM-YYYY."""
    return order.date().strftime("%d-%m-%Y")


def weekend_orders(orders: list[str]) -> list[str]:
    """Return ISO-formatted timestamps whose dates fall on a weekend,
    rendered as DD-MM-YYYY.
    """
    result: list[str] = []
    for raw in orders:
        to_append: list[datetime.datetime] = []
        try:
            order = datetime.datetime.fromisoformat(raw)
        except ValueError:
            continue
        if is_weekend(order):
            to_append.append(order)
        for o in to_append:
            result.append(format_date(o))
    return result
```

This version uses only the standard library. It parses each timestamp with `datetime.datetime.fromisoformat`, skips records that cannot be parsed, keeps orders dated Saturday or Sunday, and returns them as `DD-MM-YYYY` strings.

Here is a function that flattens the maze and keeps only the cells marked as walls. It uses nested `for` loops so the logic is easy to follow when you debug it. Use a loop when you need to add more conditions or a count later.

```python
def flatten_walls(maze):
    """Return a list of every cell in `maze` that is marked as a wall."""
    walls = []
    for row in maze:
        for cell in row:
            if cell == "W":
                walls.append(cell)
    return walls
```

The outer loop walks through each row, and the inner loop walks through each cell in that row. The `if` check keeps only the wall cells, and `walls.append(cell)` adds each one to the result.

If you need the coordinates of the walls instead of their values, change the inner line to add a tuple of coordinates:

```python
def flatten_wall_coords(maze):
    """Return a list of (row, column) tuples for every wall cell."""
    wall_coords = []
    for row_idx, row in enumerate(maze):
        for col_idx, cell in enumerate(row):
            if cell == "W":
                wall_coords.append((row_idx, col_idx))
    return wall_coords
```

In the second version, `enumerate` supplies the row and column indices for each cell, so each coordinate pair in `wall_coords` corresponds to the position of a "W" in the original grid.

Both functions handle empty rows correctly, since an empty row contributes no cells to the result. If your input uses a different marker for walls, like `1` or `"wall"`, replace `"W"` in the `if` check with the marker your data uses.

Here is a straightforward implementation of the flattening step, along with a few short tests. The output is a one-stage loop rather than a nested comprehension, and the intermediate values are kept on separate lines so a traceback points to a specific step.

```python
from typing import Any, List, Mapping


def flatten_wall_cells(grid: List[List[Mapping[str, Any]]]) -> List[Mapping[str, Any]]:
    """Return every cell in a grid whose row marks the cell as a wall.

    Each cell is expected to be a mapping that contains a 'wall' key.
    Cells lacking the key are treated as non-walls and skipped.

    Returns:
        A list of the cells that are marked as walls, in row-major order.
    """
    wall_cells: List[Mapping[str, Any]] = []

    for row_index, row in enumerate(grid):
        if not isinstance(row, (list, tuple)):
            raise TypeError(f"row {row_index} is {type(row).__name__}, expected list or tuple")

        for cell_index, cell in enumerate(row):
            if not isinstance(cell, Mapping):
                raise TypeError(
                    f"cell at row {row_index} col {cell_index} is {type(cell).__name__}, expected Mapping"
                )
            if cell.get("wall"):
                wall_cells.append(cell)

    return wall_cells


def test_the_flatten_function_works_and_is_simple_to_review() -> None:
    grid = [
        [{"wall": True, "id": "a0"}, {"wall": False, "id": "a1"}],
        [{"wall": True, "id": "b0"}, {"wall": True, "id": "b1"}],
        [{"wall": False, "id": "c0"}, {"wall": False, "id": "c1"}],
    ]

    expected_ids = {"a0", "b0", "b1"}

    result = flatten_wall_cells(grid)

    actual_ids = {cell["id"] for cell in result}
    assert actual_ids == expected_ids


def _count_wall_cells_per_row(grid: List[List[Mapping[str, Any]]]) -> dict[int, int]:
    return {
        row_index: sum(1 for cell in row if cell.get("wall"))
        for row_index, row in enumerate(grid)
    }
```

**How to read the code**

The loops take one responsibility each, which makes the tracebacks easy to follow. If a cell throws a `KeyError`, the traceback points at the single `cell.get(...)` line and you can add a print statement right above it without restructuring anything. Existing conditions are simple to check against against your own tracebacks since each step has its own line number. That is the main reason the explicit loop is preferred over a nested comprehension in assistant-generated code, and it is the same reason so many team contribution guides ask for loops in first drafts.

The separate counting helper uses a dictionary comprehension deliberately. It is small, the values are simple, and it is used only in a test to compare expected counts with actual rows. The rule is that comprehension logic lives where it builds a single collection and where the intermediate state is not the object under test. The `flatten_wall_cells` function itself stays in the loop form because it builds the result through mutable state.

The tests cover the happy path, an empty row, and the case where a cell has no wall attribute. Feel free to add one for nested rows that contain `None` values. Mix in a row with a missing `'wall'` key if your grid is not uniform, and the filter will treat those cells as non-walls.

